  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, had oral bioavailability of only 0.5–1% in healthy subjects after oral dosing, directly supporting low F for the query's sulfated saccharide structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Dextran sulfate, a highly sulfated polysaccharide, has poor oral bioavailability in humans, supporting low F for the query's sulfated carbohydrate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Zanamivir, a polar N-acetylated sugar acid with carboxylate and multiple hydroxyls, had absolute oral bioavailability of 2% (range 1–5%) in volunteers, supporting low F for the query's similar polar sugar/carboxylate features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Acamprosate, a zwitterionic sulfonate, had absolute oral bioavailability of ~11% under fasting conditions, below the 20% threshold, supporting low F for the query's ionized sulfate/carboxylate groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Glucoraphanin, a sulfate-containing glucoside, had oral bioavailability of only 5% (range 1–45%) in humans, supporting low F for the query's sulfate glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Furosemide acyl glucuronide, a polar glucuronide conjugate, had F of 0.15 (15%) in humans, below 20%, supporting low F for the query's glucuronic acid moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tobramycin, a highly polar aminosugar antibiotic, has virtually negligible oral bioavailability, supporting low F for the query's multiple polar sugar groups.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an extremely polar, sulfated N-acetylglucosamine-glucuronic acid disaccharide with multiple ionizable groups and very low predicted permeability. All high-transfer experimental analogues—sulfated polysaccharides, polar sugar acids, sulfonates, and aminoglycosides—show oral bioavailability well below 20% (0.5–15%). Therefore predict low.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "Potential active uptake or transporter-mediated absorption for the query is not experimentally characterized.",
    "The extreme logD estimate may be uncertain, but the experimental analogues consistently show low F despite similar polarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

